CREATE TABLE "fato_atendimento" (
  "sk_atendimento" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sk_paciente" integer NOT NULL,
  "sk_faixa_etaria" integer NOT NULL,
  "sk_faixa_imc" integer NOT NULL,
  "sk_cid_principal" integer NOT NULL,
  "sk_medicamento" integer NOT NULL,
  "sk_status" integer NOT NULL,
  "sk_tempo" integer NOT NULL,
  "tabagista" boolean NOT NULL,
  "qtd_comorbidades" smallint NOT NULL,
  "linha_tratamento" smallint,
  "dias_observados" integer NOT NULL,
  "qtd_reacoes" smallint NOT NULL
);

CREATE TABLE "fato_reacao_adversa" (
  "sk_reacao_fato" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sk_atendimento" integer NOT NULL,
  "sk_reacao" integer NOT NULL,
  "sk_medicamento" integer NOT NULL,
  "sk_tempo_inicio_medicamento" integer NOT NULL,
  "sk_tempo_inicio_reacao" integer NOT NULL,
  "dias_ate_reacao" integer,
  "gravidade_observada" varchar NOT NULL,
  "levou_descontinuacao" boolean NOT NULL
);

CREATE TABLE "dim_paciente" (
  "sk_paciente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_pseudonimo" varchar UNIQUE NOT NULL,
  "sexo" char(1) NOT NULL
);

CREATE TABLE "dim_faixa_etaria" (
  "sk_faixa_etaria" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descricao" varchar NOT NULL,
  "idade_min" smallint,
  "idade_max" smallint
);

CREATE TABLE "dim_faixa_imc" (
  "sk_faixa_imc" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descricao" varchar NOT NULL,
  "imc_min" numeric(4,1),
  "imc_max" numeric(4,1)
);

CREATE TABLE "dim_cid10" (
  "sk_cid" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar UNIQUE NOT NULL,
  "descricao" varchar NOT NULL,
  "grupo" varchar NOT NULL,
  "tipo" varchar NOT NULL
);

CREATE TABLE "dim_medicamento" (
  "sk_medicamento" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_atc" varchar UNIQUE NOT NULL,
  "principio_ativo" varchar NOT NULL,
  "classe_terapeutica" varchar NOT NULL
);

CREATE TABLE "dim_reacao_adversa" (
  "sk_reacao" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "termo" varchar NOT NULL,
  "soc" varchar NOT NULL,
  "gravidade_padrao" varchar NOT NULL
);

CREATE TABLE "dim_status" (
  "sk_status" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descricao" varchar UNIQUE NOT NULL
);

CREATE TABLE "dim_tempo" (
  "sk_tempo" integer PRIMARY KEY,
  "data" date,
  "mes" smallint,
  "trimestre" smallint,
  "ano" smallint
);

COMMENT ON COLUMN "fato_atendimento"."sk_medicamento" IS 'medicamento prescrito neste atendimento';

COMMENT ON COLUMN "fato_atendimento"."sk_tempo" IS 'data do atendimento';

COMMENT ON COLUMN "fato_atendimento"."tabagista" IS 'binário a confirmar com a médica';

COMMENT ON COLUMN "fato_atendimento"."linha_tratamento" IS 'ordem da tentativa terapêutica: 1 = primeiro medicamento, 2 = segundo...';

COMMENT ON COLUMN "fato_atendimento"."dias_observados" IS 'dias desde o início do medicamento até este atendimento; com o status, classifica o tratamento em qualquer horizonte';

COMMENT ON COLUMN "fato_reacao_adversa"."sk_atendimento" IS 'atendimento em que a reação foi relatada';

COMMENT ON COLUMN "fato_reacao_adversa"."sk_medicamento" IS 'medicamento que causou a reação, não necessariamente o prescrito no atendimento';

COMMENT ON COLUMN "fato_reacao_adversa"."dias_ate_reacao" IS 'sk_tempo_inicio_reacao − sk_tempo_inicio_medicamento, em dias';

COMMENT ON TABLE "dim_paciente" IS 'Pseudonimizado: sem nome, CPF, prontuário, nascimento ou endereço.';

COMMENT ON COLUMN "dim_paciente"."sexo" IS 'F | M';

COMMENT ON TABLE "dim_faixa_etaria" IS 'Faixas de órgão oficial (fonte a definir: IBGE ou Ministério da Saúde).';

COMMENT ON TABLE "dim_faixa_imc" IS 'Classificação de IMC da OMS.';

COMMENT ON TABLE "dim_cid10" IS 'Só os códigos relevantes ao atendimento psiquiátrico, filtrados na carga.';

COMMENT ON COLUMN "dim_cid10"."grupo" IS 'ex.: F30-F39';

COMMENT ON COLUMN "dim_cid10"."tipo" IS 'psiquiatrica | clinica';

COMMENT ON TABLE "dim_medicamento" IS 'Só os medicamentos relevantes ao atendimento psiquiátrico, filtrados na carga.';

COMMENT ON TABLE "dim_reacao_adversa" IS 'Termos MedDRA; só as reações relevantes aos medicamentos da base.';

COMMENT ON COLUMN "dim_status"."descricao" IS 'em uso, concluído, descontinuado por reação adversa, por ineficácia, por não adesão, outro, perdido de seguimento';

COMMENT ON TABLE "dim_tempo" IS 'Linha sk_tempo = 0 é "não informado": data, mes, trimestre e ano nulos.';

COMMENT ON COLUMN "dim_tempo"."sk_tempo" IS 'aaaammdd';

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_paciente") REFERENCES "dim_paciente" ("sk_paciente");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_faixa_etaria") REFERENCES "dim_faixa_etaria" ("sk_faixa_etaria");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_faixa_imc") REFERENCES "dim_faixa_imc" ("sk_faixa_imc");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_cid_principal") REFERENCES "dim_cid10" ("sk_cid");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_medicamento") REFERENCES "dim_medicamento" ("sk_medicamento");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_status") REFERENCES "dim_status" ("sk_status");

ALTER TABLE "fato_atendimento" ADD FOREIGN KEY ("sk_tempo") REFERENCES "dim_tempo" ("sk_tempo");

ALTER TABLE "fato_reacao_adversa" ADD FOREIGN KEY ("sk_atendimento") REFERENCES "fato_atendimento" ("sk_atendimento");

ALTER TABLE "fato_reacao_adversa" ADD FOREIGN KEY ("sk_reacao") REFERENCES "dim_reacao_adversa" ("sk_reacao");

ALTER TABLE "fato_reacao_adversa" ADD FOREIGN KEY ("sk_medicamento") REFERENCES "dim_medicamento" ("sk_medicamento");

ALTER TABLE "fato_reacao_adversa" ADD FOREIGN KEY ("sk_tempo_inicio_medicamento") REFERENCES "dim_tempo" ("sk_tempo");

ALTER TABLE "fato_reacao_adversa" ADD FOREIGN KEY ("sk_tempo_inicio_reacao") REFERENCES "dim_tempo" ("sk_tempo");

